#!/usr/bin/env node
'use strict';
// Guards against running before dist/ is built in the dev monorepo.
// In published npm tarballs, dist/postinstall.js is always present (built by CI).
const { existsSync } = require('node:fs');
const { execFileSync } = require('node:child_process');
const { join } = require('node:path');
const script = join(__dirname, 'dist', 'postinstall.js');
if (!existsSync(script)) {
  console.log('ui-leaf: dist not built yet — skipping postinstall (run `bun run build` first)');
  process.exit(0);
}
// checksums.txt (the pinned binary digests) is generated by the publish
// workflow and ships only in the npm tarball. A dev checkout (src/ present)
// has none, so there is nothing to verify a download against — skip instead
// of failing `bun install`. A published package always carries it; there
// postinstall.js fails closed if it is missing.
// INVARIANT: this relies on `src` NOT being in package.json `files`. Adding
// it would make published installs without checksums.txt skip silently.
if (
  !process.env.UI_LEAF_BINARY_PATH &&
  !existsSync(join(__dirname, 'checksums.txt')) &&
  existsSync(join(__dirname, 'src'))
) {
  console.log('ui-leaf: dev checkout without pinned checksums.txt — skipping binary download (set UI_LEAF_BINARY_PATH to use a local build)');
  process.exit(0);
}
execFileSync(process.execPath, [script], { stdio: 'inherit' });
